#include <stdio.h>

int main() {
    int L, C;
    scanf("%d %d", &L, &C);
    char grid[105][105];
    int sr = -1, sc = -1;

    for (int i = 0; i < L; i++) {
        scanf("%s", grid[i]);
        for (int j = 0; j < C; j++) {
            if (grid[i][j] == 'o') {
                sr = i;
                sc = j;
            }
        }
    }

    int pr = sr, pc = sc;
    int cr = sr, cc = sc;
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    while (1) {
        int found = 0;
        for (int d = 0; d < 4; d++) {
            int nr = cr + dr[d];
            int nc = cc + dc[d];
            if (nr >= 0 && nr < L && nc >= 0 && nc < C) {
                if (grid[nr][nc] != '.') {
                    if (nr != pr || nc != pc) {
                        pr = cr;
                        pc = cc;
                        cr = nr;
                        cc = nc;
                        found = 1;
                        break;
                    }
                }
            }
        }
        if (!found) break;
    }

    printf("%d %d\n", cr + 1, cc + 1);
    return 0;
}
